// === Tab: tab2 ===

class Tile {

  constructor(posx, posy, i, j, cellw, cellh) {
    this.posx = posx;
    this.posy = posy;
    this.posx_orig = this.posx;
    this.posy_orig = this.posy;

    this.i = i;
    this.j = j;
    this.cellw = cellw;
    this.cellh = cellh;
  }

  display() {
    //polygonal shape defined by 4-sided polygon
    let A = createVector(this.posx, this.posy);
    let B = createVector(tacke[this.i+1][this.j].posx, tacke[this.i+1][this.j].posy);
    let C = createVector( tacke[this.i+1][this.j+1].posx, tacke[this.i+1][this.j+1].posy );
    let D = createVector(tacke[this.i][this.j+1].posx, tacke[this.i][this.j+1].posy);

    fill(negative);
    beginShape();
    vertex(A.x+cellw/4, A.y+cellh/4);
    vertex(A.x+cellw/8, A.y-3*cellh/8);
    vertex(B.x-cellw/8, B.y+3*cellh/8);
    vertex(B.x-cellw/4, B.y+cellh/2);

    //top of negative and positive head
    vertex((B.x+C.x)/2-cellw/8, (B.y+C.y)/2+cellh/8);
    bezierVertex((B.x+C.x)/2-cellw/8+t, (B.y+C.y)/2+cellh/8, (B.x+C.x)/2+cellw/8-t, (B.y+C.y)/2-cellh/8, (B.x+C.x)/2+cellw/8, (B.y+C.y)/2 -cellh/8);

    vertex(C.x+cellw/4, C.y-cellh/2);
    vertex(C.x+cellw/8, C.y-3*cellh/8);

    bezierVertex( C.x+cellw/8, C.y-cellh/2+cellh/8, C.x-cellw/4 +2*t, C.y, C.x-cellw/4, C.y);

    vertex(D.x+cellw/4, D.y);
    bezierVertex(D.x+cellw/4- 2*t, D.y, D.x-cellw/8, D.y+3*cellh/8, D.x-cellw/8, D.y+3*cellh/8);

    vertex(D.x-cellw/4, D.y-cellh/4);
    vertex(D.x, D.y-cellh/4);

    vertex( D.x+cellw/4, D.y-cellh/4);

    vertex(D.x-cellw/4, A.y+cellh/4);
    vertex(A.x, A.y+cellh/4);
    endShape(CLOSE);

    //lines under wings
    stroke(positive);
    line(A.x+cellw/4, A.y+cellh/4, A.x+ cellw/2, A.y+cellh/4);
    line(D.x+cellw/4, D.y-cellh/4, D.x+cellw/2, D.y-cellh/4);

    stroke(negative);
    line(A.x+cellw/4, A.y+cellh/4, A.x-cellw/2, A.y+cellh/4);
    line(D.x-cellw/4, D.y-cellh/4, D.x-cellw/2, D.y-cellh/4);
    noStroke();

    //eyes
    fill(positive);
    ellipse((B.x+C.x)/2+cellw/8, (B.y+C.y)/2-cellh/8+cellh/8, cellh/20, cellh/20 );
    fill(negative);
    ellipse((B.x+C.x)/2-cellw/8, (B.y+C.y)/2-cellh/8+cellh/8, cellh/20, cellh/20 );
  }

  move() {
    rndx = map(noise(x1, y1, z1), 0, 1, -noisex, noisex);
    rndy = map(noise(x2, y2, z2), 0, 1, -noisey, noisey);
    this.posx = this.posx_orig+rndx;
    this.posy = this.posy_orig+rndy;
  }
}


